import{_ as t,c as r,o as e,a5 as i}from"./chunks/framework.DorIfSpC.js";const g=JSON.parse('{"title":"CS336 自學筆記 Week 1：Micrograd 深度拆解","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/learning/cs336/CS336_Week1_Micrograd_Deep_Dive"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/learning/cs336/CS336_Week1_Micrograd_Deep_Dive"}],["meta",{"property":"og:title","content":"CS336 自學筆記 Week 1：Micrograd 深度拆解 | 星智未來"}],["meta",{"name":"twitter:title","content":"CS336 自學筆記 Week 1：Micrograd 深度拆解 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"CS336 自學筆記 Week 1：Micrograd 深度拆解\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/learning/cs336/CS336_Week1_Micrograd_Deep_Dive\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/learning/cs336/CS336_Week1_Micrograd_Deep_Dive\\"}}"]]},"headers":[],"relativePath":"learning/cs336/CS336_Week1_Micrograd_Deep_Dive.md","filePath":"learning/cs336/CS336_Week1_Micrograd_Deep_Dive.md","lastUpdated":1766454910000}'),n={name:"learning/cs336/CS336_Week1_Micrograd_Deep_Dive.md"};function s(l,a,o,d,p,h){return e(),r("div",null,[...a[0]||(a[0]=[i(`<h1 id="cs336-自學筆記-week-1-micrograd-深度拆解" tabindex="-1">CS336 自學筆記 Week 1：Micrograd 深度拆解 <a class="header-anchor" href="#cs336-自學筆記-week-1-micrograd-深度拆解" aria-label="Permalink to &quot;CS336 自學筆記 Week 1：Micrograd 深度拆解&quot;">​</a></h1><blockquote><p>當我們把「可怕的術語」翻譯成「12 歲也懂的白話文」，一切就不一樣了。</p></blockquote><p><strong>作者</strong>：Ray<br><strong>日期</strong>：2025 年 12 月</p><hr><h2 id="前言-這週我學了什麼" tabindex="-1">前言：這週我學了什麼？ <a class="header-anchor" href="#前言-這週我學了什麼" aria-label="Permalink to &quot;前言：這週我學了什麼？&quot;">​</a></h2><p>按照<a href="./CS336_Learning_Path_Blog">先修攻略</a>的規劃，Week 1-2 要跟著 Karpathy 的 <a href="https://www.youtube.com/watch?v=VMj-3S1tku0" target="_blank" rel="noreferrer">micrograd 影片</a> 學習自動微分。</p><p>但在動手寫程式之前，我發現自己對很多「基礎概念」其實一知半解。這篇文章記錄了我在學習過程中問自己的問題，以及我找到的答案。</p><p><strong>我的學習原則</strong>：如果不能用 12 歲小朋友聽得懂的話解釋，代表我自己也沒真正理解。</p><hr><h2 id="part-1-micrograd-是什麼" tabindex="-1">Part 1：Micrograd 是什麼？ <a class="header-anchor" href="#part-1-micrograd-是什麼" aria-label="Permalink to &quot;Part 1：Micrograd 是什麼？&quot;">​</a></h2><h3 id="🔬-名字拆解" tabindex="-1">🔬 名字拆解 <a class="header-anchor" href="#🔬-名字拆解" aria-label="Permalink to &quot;🔬 名字拆解&quot;">​</a></h3><p><strong>Micro</strong> + <strong>grad</strong> = Micrograd</p><table tabindex="0"><thead><tr><th>部分</th><th>意思</th></tr></thead><tbody><tr><td><strong>Micro</strong></td><td>微小的——整個專案只有約 150 行程式碼</td></tr><tr><td><strong>grad</strong></td><td>Gradient（梯度）的縮寫——這是整個專案的核心功能</td></tr></tbody></table><p>所以 <strong>Micrograd = 微型的梯度計算引擎</strong>。</p><p>它想表達的是：「這是一個超級小、但能真正計算梯度的引擎」。</p><h3 id="這個專案在做什麼" tabindex="-1">這個專案在做什麼？ <a class="header-anchor" href="#這個專案在做什麼" aria-label="Permalink to &quot;這個專案在做什麼？&quot;">​</a></h3><p>Micrograd 實現了兩件事：</p><ol><li><strong>自動微分引擎</strong>（約 100 行）：讓電腦自動計算梯度</li><li><strong>神經網路模組</strong>（約 50 行）：用這個引擎建構神經網路</li></ol><p>相比之下，PyTorch 有幾十萬行程式碼。Micrograd 就像把大象縮小成螞蟻，但螞蟻還是會走路！</p><h3 id="命名傳統" tabindex="-1">命名傳統 <a class="header-anchor" href="#命名傳統" aria-label="Permalink to &quot;命名傳統&quot;">​</a></h3><p>在深度學習領域，很多框架都用類似的命名：</p><table tabindex="0"><thead><tr><th>名稱</th><th>意思</th></tr></thead><tbody><tr><td><strong>Autograd</strong></td><td>PyTorch 的自動微分模組</td></tr><tr><td><strong>Micrograd</strong></td><td>超迷你版的 autograd</td></tr><tr><td><strong>Tinygrad</strong></td><td>另一個小型框架（比 micrograd 大一些）</td></tr></tbody></table><hr><h2 id="part-2-核心概念的白話解釋" tabindex="-1">Part 2：核心概念的白話解釋 <a class="header-anchor" href="#part-2-核心概念的白話解釋" aria-label="Permalink to &quot;Part 2：核心概念的白話解釋&quot;">​</a></h2><p>學習 micrograd 之前，需要理解幾個核心概念。以下是我整理的「12 歲版」解釋。</p><h3 id="🧠-神經網路-neural-network" tabindex="-1">🧠 神經網路 (Neural Network) <a class="header-anchor" href="#🧠-神經網路-neural-network" aria-label="Permalink to &quot;🧠 神經網路 (Neural Network)&quot;">​</a></h3><p>想像一下你的大腦 🧠</p><p>你的大腦裡有很多「神經元」，它們彼此連接。當你學習新東西時，這些連接會變強或變弱。</p><p><strong>神經網路就是模仿大腦的電腦程式</strong>：</p><ul><li>有很多小「節點」（像神經元）</li><li>節點之間有「連線」（像神經連接）</li><li>學習時，連線的「強度」會調整</li></ul><p><strong>例子</strong>：教電腦分辨貓和狗</p><ol><li>給電腦看很多貓狗照片</li><li>電腦猜錯時，調整連線強度</li><li>猜對越來越多，就學會了！</li></ol><hr><h3 id="📈-前向傳播-vs-反向傳播" tabindex="-1">📈 前向傳播 vs 反向傳播 <a class="header-anchor" href="#📈-前向傳播-vs-反向傳播" aria-label="Permalink to &quot;📈 前向傳播 vs 反向傳播&quot;">​</a></h3><p>這是神經網路的「去程」和「回程」。</p><p><strong>前向傳播 (Forward Pass)</strong>：計算的「去程」</p><p>想像你在算一道數學題：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a = 2</span></span>
<span class="line"><span>b = 3</span></span>
<span class="line"><span>c = a + b      → c = 5</span></span>
<span class="line"><span>d = c × 2      → d = 10</span></span></code></pre></div><p>你從最開始的數字（a、b），一步一步算到最後的答案（d）。資料<strong>往前流動</strong>。</p><p><strong>反向傳播 (Backpropagation)</strong>：計算的「回程」</p><p>想像你考試考了 60 分，想知道「哪裡錯了」：</p><ul><li>你往回檢查每一題</li><li>找出哪些地方需要改進</li></ul><p>反向傳播就是這樣：</p><ol><li>電腦算出一個答案</li><li>發現答案不對（有「誤差」）</li><li><strong>往回追查</strong>：是哪些數字、哪些連線造成的？</li><li>找出每個部分的「責任」有多大</li></ol><hr><h3 id="🎯-梯度-gradient" tabindex="-1">🎯 梯度 (Gradient) <a class="header-anchor" href="#🎯-梯度-gradient" aria-label="Permalink to &quot;🎯 梯度 (Gradient)&quot;">​</a></h3><p>梯度就是告訴我們**「要怎麼調整才會變好」**的指引。</p><p>想像你在爬山，但你閉著眼睛：</p><ul><li>梯度就像告訴你「往左走會上坡，往右走會下坡」</li><li>如果你想下山（減少誤差），就往梯度說的方向走</li></ul><p><strong>數學上</strong>：梯度告訴我們「如果我把這個數字調大一點點，最終答案會變大還是變小？變多少？」</p><hr><h3 id="🌳-計算圖-dag" tabindex="-1">🌳 計算圖 / DAG <a class="header-anchor" href="#🌳-計算圖-dag" aria-label="Permalink to &quot;🌳 計算圖 / DAG&quot;">​</a></h3><p>DAG 是「有向無環圖」(Directed Acyclic Graph)，聽起來很複雜，其實很簡單。</p><p>想像一個<strong>家族樹</strong> 🌳：</p><ul><li>爺爺奶奶 → 爸爸媽媽 → 你</li><li>有方向（從上到下）</li><li>不會繞圈（你不會是自己的祖先）</li></ul><p>計算圖就是把數學計算畫成這樣的樹：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    a        b</span></span>
<span class="line"><span>     \\      /</span></span>
<span class="line"><span>      \\    /</span></span>
<span class="line"><span>        +        ← 加法節點</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        c</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        ×        ← 乘法節點（c × 2）</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        d</span></span></code></pre></div><p>這樣電腦就知道「d 是怎麼從 a、b 一步步算出來的」，反向傳播時就能順著這棵樹往回走。</p><hr><h3 id="🔌-relu-激活函數" tabindex="-1">🔌 ReLU 激活函數 <a class="header-anchor" href="#🔌-relu-激活函數" aria-label="Permalink to &quot;🔌 ReLU 激活函數&quot;">​</a></h3><p>ReLU 是神經網路裡最常用的「開關」。</p><p>規則超級簡單：</p><ul><li>如果數字 &gt; 0，就保持原樣</li><li>如果數字 ≤ 0，就變成 0</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ReLU(5)  = 5</span></span>
<span class="line"><span>ReLU(-3) = 0</span></span>
<span class="line"><span>ReLU(0)  = 0</span></span></code></pre></div><p><strong>為什麼需要它？</strong></p><p>如果神經網路只有加法和乘法，它只能學「直線」的關係。有了 ReLU 這種「非線性」的東西，神經網路才能學會複雜的「彎彎曲曲」的關係！</p><hr><h2 id="part-3-微積分不可怕" tabindex="-1">Part 3：微積分不可怕 <a class="header-anchor" href="#part-3-微積分不可怕" aria-label="Permalink to &quot;Part 3：微積分不可怕&quot;">​</a></h2><p>學 micrograd 一定會碰到微積分。很多人聽到就害怕，但其實核心概念很直覺。</p><h3 id="微積分在解決什麼問題" tabindex="-1">微積分在解決什麼問題？ <a class="header-anchor" href="#微積分在解決什麼問題" aria-label="Permalink to &quot;微積分在解決什麼問題？&quot;">​</a></h3><p>只有兩個：</p><ol><li><strong>東西變化的速度有多快？</strong> （微分）</li><li><strong>把很多小東西加起來是多少？</strong> （積分）</li></ol><p>就這樣！</p><h3 id="🚗-微分-用汽車來理解" tabindex="-1">🚗 微分：用汽車來理解 <a class="header-anchor" href="#🚗-微分-用汽車來理解" aria-label="Permalink to &quot;🚗 微分：用汽車來理解&quot;">​</a></h3><p>想像你坐在車上，看著儀表板：</p><ul><li><strong>里程表</strong>：顯示你「總共走了多遠」（例如：50 公里）</li><li><strong>時速表</strong>：顯示你「現在有多快」（例如：60 公里/小時）</li></ul><p>這兩個數字有什麼關係？</p><blockquote><p>時速就是「距離變化的速度」</p></blockquote><p><strong>微分就是：已知「總量」，求出「變化速度」</strong></p><table tabindex="0"><thead><tr><th>數學說法</th><th>白話文</th></tr></thead><tbody><tr><td>對位置微分</td><td>求速度（位置變化多快）</td></tr><tr><td>對速度微分</td><td>求加速度（速度變化多快）</td></tr></tbody></table><h3 id="🍕-積分-用披薩來理解" tabindex="-1">🍕 積分：用披薩來理解 <a class="header-anchor" href="#🍕-積分-用披薩來理解" aria-label="Permalink to &quot;🍕 積分：用披薩來理解&quot;">​</a></h3><p>想像你要算一個奇形怪狀的披薩面積。正方形、三角形有公式，但怪形狀怎麼辦？</p><p><strong>積分的方法：切成很多小塊！</strong></p><p>把它切成很多很多細長條，每個長條近似長方形，長方形面積很好算，然後把所有長條的面積<strong>加起來</strong>。</p><p>切越細 → 越準確。切到無限細 → 完美準確！</p><p><strong>這就是積分：把無限多的小東西加起來</strong></p><h3 id="🔄-微分和積分是相反的" tabindex="-1">🔄 微分和積分是相反的！ <a class="header-anchor" href="#🔄-微分和積分是相反的" aria-label="Permalink to &quot;🔄 微分和積分是相反的！&quot;">​</a></h3><p>這是微積分最美妙的發現：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        微分</span></span>
<span class="line"><span>    ──────────→</span></span>
<span class="line"><span>距離              速度</span></span>
<span class="line"><span>    ←──────────</span></span>
<span class="line"><span>        積分</span></span></code></pre></div><p>它們互為逆運算，就像加法和減法一樣！</p><h3 id="這跟-micrograd-有什麼關係" tabindex="-1">這跟 Micrograd 有什麼關係？ <a class="header-anchor" href="#這跟-micrograd-有什麼關係" aria-label="Permalink to &quot;這跟 Micrograd 有什麼關係？&quot;">​</a></h3><p>在訓練神經網路時：</p><ol><li>我們有一個「損失函數」：衡量 AI 的答案有多錯</li><li>我們想找出「怎麼調整權重才能減少錯誤」</li><li><strong>這就需要微分！</strong> 對損失函數微分（求梯度），梯度告訴我們怎麼調整</li><li><strong>Micrograd 的 <code>backward()</code> 就是在自動做微分</strong></li></ol><hr><h2 id="part-4-為什麼數學術語這麼難懂" tabindex="-1">Part 4：為什麼數學術語這麼難懂？ <a class="header-anchor" href="#part-4-為什麼數學術語這麼難懂" aria-label="Permalink to &quot;Part 4：為什麼數學術語這麼難懂？&quot;">​</a></h2><p>學習過程中，我一直有個疑問：為什麼這些術語這麼不直覺？</p><h3 id="「微積分」這三個字" tabindex="-1">「微積分」這三個字 <a class="header-anchor" href="#「微積分」這三個字" aria-label="Permalink to &quot;「微積分」這三個字&quot;">​</a></h3><p>其實是兩個詞組合：<strong>微分</strong> + <strong>積分</strong></p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td><strong>微分</strong></td><td>微小的分割（把變化切成極小來分析）</td></tr><tr><td><strong>積分</strong></td><td>累積的份量（把微小的部分加起來）</td></tr></tbody></table><p>英文 <strong>Calculus</strong> 來自拉丁文，意思是「小石頭」——古羅馬人用小石頭來算數。</p><h3 id="數學命名的荒謬案例" tabindex="-1">數學命名的荒謬案例 <a class="header-anchor" href="#數學命名的荒謬案例" aria-label="Permalink to &quot;數學命名的荒謬案例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>術語</th><th>問題</th></tr></thead><tbody><tr><td><strong>虛數</strong> (Imaginary)</td><td>叫「虛」是因為當年數學家覺得「不可能存在」。但它在物理學、工程學超級有用，一點都不「虛」！</td></tr><tr><td><strong>無理數</strong> (Irrational)</td><td>原意是「不理性的、瘋狂的」。古希臘人發現 √2 無法寫成分數，嚇壞了。但 π 超級有用，哪裡「瘋狂」？</td></tr><tr><td><strong>負數</strong> (Negative)</td><td>Negative 有「負面」的意思，但 -10°C 只是方向相反，沒有什麼「不好」。</td></tr></tbody></table><h3 id="為什麼不改掉" tabindex="-1">為什麼不改掉？ <a class="header-anchor" href="#為什麼不改掉" aria-label="Permalink to &quot;為什麼不改掉？&quot;">​</a></h3><ol><li><strong>慣性太強</strong>：幾百年的教科書都用這些詞</li><li><strong>國際溝通</strong>：全世界用同樣術語，改了會混亂</li><li><strong>數學家不在乎</strong>：「定義清楚就好，名字只是標籤」</li></ol><h3 id="我的結論" tabindex="-1">我的結論 <a class="header-anchor" href="#我的結論" aria-label="Permalink to &quot;我的結論&quot;">​</a></h3><blockquote><p><strong>數學術語「定義精準」，但「命名不精準」</strong></p></blockquote><p>術語只是標籤，重要的是<strong>背後的概念</strong>。不管叫「微分」還是「求變化速度」，本質都是「某個東西變化有多快」。</p><p><strong>給初學者的建議</strong>：</p><ol><li>不要被術語嚇到——很多嚇人的名字背後是簡單的概念</li><li>先理解概念，再記術語</li><li>在腦中建立「白話翻譯」</li><li>不要以為聽不懂是自己笨——有時候真的是命名的問題！</li></ol><hr><h2 id="part-5-micrograd-程式結構" tabindex="-1">Part 5：Micrograd 程式結構 <a class="header-anchor" href="#part-5-micrograd-程式結構" aria-label="Permalink to &quot;Part 5：Micrograd 程式結構&quot;">​</a></h2><h3 id="engine-py-—-核心引擎" tabindex="-1"><code>engine.py</code> — 核心引擎 <a class="header-anchor" href="#engine-py-—-核心引擎" aria-label="Permalink to &quot;\`engine.py\` — 核心引擎&quot;">​</a></h3><p>主要是一個叫 <code>Value</code> 的類別：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Value(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 創造一個「有記憶的數字」</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Value(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># c 會記得它是 a + b 來的</span></span></code></pre></div><p>每個 <code>Value</code> 包含：</p><table tabindex="0"><thead><tr><th>屬性</th><th>功能</th></tr></thead><tbody><tr><td><code>data</code></td><td>實際的數字值</td></tr><tr><td><code>grad</code></td><td>這個數字的梯度</td></tr><tr><td><code>_backward</code></td><td>如何往回傳梯度</td></tr><tr><td><code>_prev</code></td><td>記得自己是從哪些數字算出來的</td></tr></tbody></table><h3 id="nn-py-—-神經網路模組" tabindex="-1"><code>nn.py</code> — 神經網路模組 <a class="header-anchor" href="#nn-py-—-神經網路模組" aria-label="Permalink to &quot;\`nn.py\` — 神經網路模組&quot;">​</a></h3><table tabindex="0"><thead><tr><th>類別</th><th>功能</th></tr></thead><tbody><tr><td><strong>Neuron</strong></td><td>一個神經元</td></tr><tr><td><strong>Layer</strong></td><td>一層（很多神經元）</td></tr><tr><td><strong>MLP</strong></td><td>多層神經網路</td></tr></tbody></table><hr><h2 id="part-6-本週總結" tabindex="-1">Part 6：本週總結 <a class="header-anchor" href="#part-6-本週總結" aria-label="Permalink to &quot;Part 6：本週總結&quot;">​</a></h2><h3 id="概念對照表" tabindex="-1">概念對照表 <a class="header-anchor" href="#概念對照表" aria-label="Permalink to &quot;概念對照表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>專有名詞</th><th>12 歲版解釋</th></tr></thead><tbody><tr><td>神經網路</td><td>模仿大腦的電腦程式，會學習</td></tr><tr><td>純量</td><td>一個單獨的數字</td></tr><tr><td>前向傳播</td><td>從輸入算到輸出</td></tr><tr><td>反向傳播</td><td>從輸出往回找，看誰要負責</td></tr><tr><td>梯度</td><td>告訴你「往哪調整會變好」的箭頭</td></tr><tr><td>自動微分</td><td>電腦自動幫你算梯度</td></tr><tr><td>計算圖</td><td>把計算過程畫成家族樹</td></tr><tr><td>損失函數</td><td>衡量「錯多少」的分數</td></tr><tr><td>ReLU</td><td>負數變 0，正數不變的開關</td></tr><tr><td>MLP</td><td>好幾層神經元疊在一起</td></tr><tr><td>權重</td><td>連線的強度</td></tr><tr><td>微分</td><td>求變化速度</td></tr><tr><td>積分</td><td>把小東西累加起來</td></tr></tbody></table><h3 id="本週心得" tabindex="-1">本週心得 <a class="header-anchor" href="#本週心得" aria-label="Permalink to &quot;本週心得&quot;">​</a></h3><ol><li><strong>先理解「為什麼」比「怎麼做」更重要</strong>：知道梯度的意義，比死背公式有用</li><li><strong>術語是障礙，但可以克服</strong>：翻譯成白話文，一切就清楚了</li><li><strong>Micrograd 的精髓是簡單</strong>：150 行程式包含 AI 學習的所有核心概念</li></ol><h3 id="下週預告" tabindex="-1">下週預告 <a class="header-anchor" href="#下週預告" aria-label="Permalink to &quot;下週預告&quot;">​</a></h3><p>Week 2 會繼續深入 micrograd，實際動手寫程式碼，實作：</p><ul><li>Chain rule 的程式碼實現</li><li>完整的反向傳播流程</li><li>簡單的神經網路訓練</li></ul><hr><h2 id="延伸資源" tabindex="-1">延伸資源 <a class="header-anchor" href="#延伸資源" aria-label="Permalink to &quot;延伸資源&quot;">​</a></h2><h3 id="本週使用的資源" tabindex="-1">本週使用的資源 <a class="header-anchor" href="#本週使用的資源" aria-label="Permalink to &quot;本週使用的資源&quot;">​</a></h3><ul><li>🎥 <a href="https://www.youtube.com/watch?v=VMj-3S1tku0" target="_blank" rel="noreferrer">Karpathy - micrograd 影片</a></li><li>💻 <a href="https://github.com/karpathy/micrograd" target="_blank" rel="noreferrer">micrograd GitHub</a></li><li>🎥 <a href="https://www.youtube.com/playlist?list=PLZHQObOWTQDMsr9K-rj53DwVRMYO3t5Yr" target="_blank" rel="noreferrer">3Blue1Brown 微積分系列</a></li></ul><h3 id="如果你卡住了" tabindex="-1">如果你卡住了 <a class="header-anchor" href="#如果你卡住了" aria-label="Permalink to &quot;如果你卡住了&quot;">​</a></h3><ul><li>Chain rule 不懂 → 看 3Blue1Brown 微積分第 1-4 集</li><li>不懂為什麼要算 gradient → 看 <a href="https://www.youtube.com/playlist?list=PLZHQObOWTQDNU6R1_67000Dx_ZCJB-3pi" target="_blank" rel="noreferrer">3Blue1Brown 神經網路系列</a></li></ul><hr><p><em>下一篇：<a href="./">Week 2 - Micrograd 實作篇</a></em></p><p><em>如果這篇文章對你有幫助，歡迎分享給同樣在自學 LLM 的朋友！</em></p>`,136)])])}const b=t(n,[["render",s]]);export{g as __pageData,b as default};
